import{_ as o,C as a,o as l,c as i,j as r,a as u,E as s,a2 as n}from"./chunks/framework.TaNiW7i8.js";const q=JSON.parse('{"title":"Accueil","description":"","frontmatter":{"title":"Accueil"},"headers":[],"relativePath":"guide/home.md","filePath":"guide/home.md"}'),c={name:"guide/home.md"};function g(d,e,p,h,m,v){const t=a("Capture");return l(),i("div",null,[e[0]||(e[0]=r("h1",{id:"accueil",tabindex:"-1"},[u("Accueil "),r("a",{class:"header-anchor",href:"#accueil","aria-label":'Permalink to "Accueil"'},"​")],-1)),e[1]||(e[1]=r("p",null,"L'accueil est l'écran de départ de Kessho. Il répond à une question : où en est ma mémoire ? Vous y voyez ce qu'elle pèse, comment ses notes se relient, où elles se trouvent et ce qui vient d'y entrer.",-1)),s(t,{name:"accueil",alt:"L'accueil de Kessho : les mesures de la mémoire, le graphe de ses relations et les dépôts récents."}),e[2]||(e[2]=n('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>L&#39;accueil s&#39;ouvre dans le premier onglet, <strong>Tableau de bord</strong>, et se lit de haut en bas, avec une colonne à droite.</p><ul><li><strong>En-tête</strong> : « Session ouverte », puis le titre <strong>Accueil</strong>. À droite, la date du dernier dépôt et le résumé « 13 notes · 47.1 Ko ».</li><li><strong>Bandeau de mesures</strong> : quatre chiffres — <strong>Notes</strong>, <strong>Volume</strong>, <strong>Projets actifs</strong>, <strong>Domaines</strong>. Un tiret « — » remplace un chiffre qui n&#39;a pas pu être mesuré.</li><li><strong>La mémoire en relations</strong> : le graphe de la mémoire, avec son champ de recherche (« Chercher une note, un projet… »), les boutons <strong>Voir en liste</strong> et <strong>Ouvrir dans un onglet</strong>, les filtres par niveau (<strong>Domaine</strong>, <strong>Concept</strong>, <strong>Projet</strong>, <strong>Note</strong>, <strong>Archives</strong>) et un bouton <strong>Réinitialiser</strong>. Le détail est dans <a href="/Kessho/guide/graph.html">Graphe</a>.</li><li><strong>Tableau des zones</strong> : une ligne par zone, avec quatre colonnes — <strong>Zone mémorielle</strong>, <strong>Notes</strong>, <strong>Dernier dépôt</strong>, <strong>Densité</strong>. Les zones les plus fournies viennent en premier ; la ligne « (hors-zone) » est toujours la dernière. Voir <a href="/Kessho/guide/zones.html">Zones</a>.</li><li><strong>Dépôts récents</strong> (colonne de droite) : les seize notes les plus récentes, avec leur date, et le compte du jour (« 2 aujourd’hui »). Une mémoire sans dépôt affiche « Aucun dépôt pour l’instant ».</li><li><strong>Statistiques de la mémoire</strong> (plus bas, avec le bouton <strong>Actualiser</strong>) : des cartes, dont les <strong>Projets Actifs Détectés</strong>, sous forme d&#39;étiquettes.</li><li><strong>Score de santé de la mémoire</strong> : un pourcentage, le nombre d&#39;anomalies (« anomalies sur N fichiers ») et leur répartition entre ce que l&#39;application répare, ce qu&#39;il faut confier à un agent et ce qui est seulement signalé.</li><li><strong>État de la machine</strong> (tout en bas) : combien de connecteurs sont configurés (« 6 connecteurs sur 8 configurés »), la version, et le bouton <strong>Ouvrir les réglages</strong>.</li></ul><p>Au-dessus de l&#39;écran, un bandeau peut apparaître : « Migration disponible » (une installation précédente est détectée, voir <a href="/Kessho/guide/vault.html">Choisir sa mémoire</a>) ou « macOS fait tourner une copie temporaire » (voir <a href="/Kessho/guide/agents.html">Connecter ses agents</a>).</p><h3 id="autour-de-l-accueil" tabindex="-1">Autour de l&#39;accueil <a class="header-anchor" href="#autour-de-l-accueil" aria-label="Permalink to &quot;Autour de l&#39;accueil&quot;">​</a></h3><ul><li><strong>Barre latérale</strong> : <strong>Clés de contexte</strong> et <strong>Chercher</strong> en haut ; en dessous, <strong>Zones de la mémoire</strong> avec le nombre de notes de chaque zone ; en bas, le sélecteur de langue, <strong>Aide</strong> et <strong>Réglages</strong>.</li><li><strong>Barre d&#39;onglets</strong> : l&#39;accueil est toujours le premier onglet ; les zones, les notes et les réglages s&#39;ouvrent dans les suivants. En haut à droite, votre pastille de profil et le témoin de fraîcheur (voir <a href="/Kessho/guide/zones.html">Zones</a>).</li><li><strong>Barre d&#39;état</strong> (en bas) : le nom de la mémoire, son nombre de notes, la date du dernier dépôt, l&#39;état <strong>GIT</strong>, la <strong>SANTÉ</strong>, le compte <strong>AGENTS</strong> et la version.</li></ul><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="ouvrir-une-note-recente" tabindex="-1">Ouvrir une note récente <a class="header-anchor" href="#ouvrir-une-note-recente" aria-label="Permalink to &quot;Ouvrir une note récente&quot;">​</a></h3><p>Dans <strong>Dépôts récents</strong>, cliquez sur une ligne : la note s&#39;ouvre dans un onglet. Pour lire et modifier une note, voir <a href="/Kessho/guide/atom.html">Atome et éditeur</a>.</p><h3 id="explorer-le-graphe" tabindex="-1">Explorer le graphe <a class="header-anchor" href="#explorer-le-graphe" aria-label="Permalink to &quot;Explorer le graphe&quot;">​</a></h3><p>Dans <strong>La mémoire en relations</strong>, cliquez sur <strong>Ouvrir dans un onglet</strong> pour lui donner toute la place, ou sur <strong>Voir en liste</strong> pour lire les notes en liste plutôt qu&#39;en dessin. Voir <a href="/Kessho/guide/graph.html">Graphe</a>.</p><h3 id="actualiser-les-chiffres" tabindex="-1">Actualiser les chiffres <a class="header-anchor" href="#actualiser-les-chiffres" aria-label="Permalink to &quot;Actualiser les chiffres&quot;">​</a></h3><p>Dans <strong>Statistiques de la mémoire</strong>, cliquez sur <strong>Actualiser</strong>. La section relit le dossier (le bouton affiche « Scan en cours… » pendant la lecture).</p><h3 id="verifier-la-sante-et-reparer" tabindex="-1">Vérifier la santé et réparer <a class="header-anchor" href="#verifier-la-sante-et-reparer" aria-label="Permalink to &quot;Vérifier la santé et réparer&quot;">​</a></h3><p>Le <strong>Score de santé de la mémoire</strong> repère des défauts : un lien cassé, une note orpheline, un frontmatter illisible, un index de zone absent…</p><ol><li>Cliquez sur <strong>Préparer la réparation</strong>. Le bouton est grisé s&#39;il n&#39;y a rien que l&#39;application puisse réparer seule.</li><li>Kessho calcule un plan (« Calcul du plan… ») et le résume : « N constats réparés par N corrections sur N fichiers ». <strong>Voir les fichiers</strong> déplie la liste.</li><li>Cliquez sur <strong>Appliquer les N corrections</strong>, ou sur <strong>Annuler</strong>. Rien n&#39;est écrit avant ce clic.</li><li>Le résultat s&#39;affiche (« N constats réparés. ») et le scan est relancé.</li></ol><p>Si la mémoire change entre l&#39;aperçu et le clic, Kessho refuse d&#39;appliquer un plan périmé (« Le plan a changé depuis qu&#39;il a été montré : rien n&#39;a été écrit ») et propose <strong>Revoir le plan</strong>.</p><p>Ce que l&#39;application ne répare pas est compté à part : « N tâches pour un agent ». Le bouton <strong>Copier la consigne</strong> copie la phrase à donner à votre agent.</p><h3 id="retrouver-ou-vous-en-etiez-les-cles-de-contexte" tabindex="-1">Retrouver où vous en étiez : les clés de contexte <a class="header-anchor" href="#retrouver-ou-vous-en-etiez-les-cles-de-contexte" aria-label="Permalink to &quot;Retrouver où vous en étiez : les clés de contexte&quot;">​</a></h3>',19)),s(t,{name:"cles-de-contexte",alt:"L'écran des clés de contexte : un projet avec son résumé, et un domaine sans résumé, à donner à un agent pour qu'il retrouve où vous en étiez."}),e[3]||(e[3]=n('<ol><li>Dans la barre latérale, cliquez sur <strong>Clés de contexte</strong>. L&#39;écran s&#39;ouvre dans un onglet.</li><li>Chaque ligne du tableau est un projet ou un domaine : son titre et son identifiant (ce que vous donnez à un agent), son résumé, le nombre d&#39;archives, la date de la dernière session et la portée (<strong>Travail</strong> ou <strong>Personnel</strong>). Un résumé trop long est coupé : passez la souris dessus pour le lire en entier.</li><li>Affinez la liste : le champ <strong>Filtrer</strong>, <strong>Trier par</strong> (<strong>Dernière session</strong>, <strong>Volumétrie</strong>, <strong>A → Z</strong>), <strong>Type</strong> (<strong>Tout</strong>, <strong>Projets</strong>, <strong>Domaines</strong>), <strong>Portée</strong> (<strong>Toutes portées</strong>, <strong>Travail</strong>, <strong>Personnel</strong>), et la case <strong>Sans résumé</strong>.</li><li>Cliquez sur le titre d&#39;une ligne pour ouvrir le projet dans son onglet, ou sur <strong>Ouvrir le contexte</strong> pour lire son fichier de contexte.</li></ol><p>Une ligne sans résumé affiche « Aucun résumé » ; un compte en haut de l&#39;écran dit combien il en manque (un agent en écrit un avec <code>mem_set_summary</code>). Un contexte qui ne se lit pas porte l&#39;alerte « Contexte illisible — son frontmatter ne se parse pas ».</p><h3 id="voir-ou-en-sont-les-connecteurs" tabindex="-1">Voir où en sont les connecteurs <a class="header-anchor" href="#voir-ou-en-sont-les-connecteurs" aria-label="Permalink to &quot;Voir où en sont les connecteurs&quot;">​</a></h3><p>Dans <strong>État de la machine</strong>, cliquez sur <strong>Ouvrir les réglages</strong> : vous arrivez dans les réglages, où vous pouvez <a href="/Kessho/guide/agents.html">connecter vos agents</a>.</p>',4))])}const b=o(c,[["render",g]]);export{q as __pageData,b as default};
